#include "stdlib/stats/base/dists/binomial/quantile.h"
#include "stdlib/stats/base/dists/binomial/cdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/constants/float64/pinf.h"
#include "stdlib/constants/float64/sqrt_two.h"
#include "stdlib/math/base/assert/is_nonnegative_integer.h"
#include "stdlib/math/base/special/sqrt.h"
#include "stdlib/math/base/special/round.h"
#include "stdlib/math/base/special/erfcinv.h"

/**
* Returns the quantile function for a binomial distribution with number of trials `n` and success probability `p` at value `r`.
*
* @param r  input probability
* @param n  number of trials
* @param p  success probability
* @return   quantile
*
* @example
* double y = stdlib_base_dists_binomial_quantile( 0.4, 20, 0.2 );
* // returns 3
*/
double stdlib_base_dists_binomial_quantile( const double r, const double n, const double p ) {
	if (
		stdlib_base_is_nan( r ) ||
		stdlib_base_is_nan( n ) ||
		stdlib_base_is_nan( p ) ||
		n < 0.0 ||
		p < 0.0 ||
		p > 1.0 ||
		r < 0.0 ||
		r > 1.0 ||
		!stdlib_base_is_nonnegative_integer( n ) ||
		n == STDLIB_CONSTANT_FLOAT64_PINF
	) {
		return 0.0 / 0.0;
	}

	if ( r == 1.0 || p == 1.0 ) {
		return n;
	}
	if ( r == 0.0 || p == 0.0 || n == 0 ) {
		return 0.0;
	}

	// Cornish-Fisher expansion:
	double mu = n * p;
	double sigma = stdlib_base_sqrt( n * p * ( 1.0 - p ) );
	double sigmaInv = 1.0 / sigma;
	double x, x2, corr, guess;
	
	if ( r < 0.5 ) {
		x = -stdlib_base_erfcinv( 2.0 * r ) * STDLIB_CONSTANT_FLOAT64_SQRT_TWO;
	} else {
		x = stdlib_base_erfcinv( 2.0 * ( 1.0 - r ) ) * STDLIB_CONSTANT_FLOAT64_SQRT_TWO;
	}
	x2 = x * x;
	
	// Skewness correction:
	corr = x + ( sigmaInv * ( x2 - 1.0 ) / 6.0 );
	guess = stdlib_base_round( mu + ( sigma * corr ) );
	
	// Search for the exact quantile:
	if ( stdlib_base_dists_binomial_cdf( guess, n, p ) >= r ) {
		// Search left
		while ( guess > 0 && stdlib_base_dists_binomial_cdf( guess - 1, n, p ) >= r ) {
			guess -= 1;
		}
		return guess;
	} else {
		// Search right
		guess += 1;
		while ( stdlib_base_dists_binomial_cdf( guess, n, p ) < r ) {
			guess += 1;
		}
		return guess;
	}
}
